func (q *Queries) NextHuntByOldestSearched(ctx context.Context, arg NextHuntByOldestSearchedParams) ([]HuntQueue, error) {
	rows, err := q.db.QueryContext(ctx, nextHuntByOldestSearched, arg.Class, arg.Now, arg.PageSize)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []HuntQueue{}
	for rows.Next() {
		var i HuntQueue
		if err := rows.Scan(
			&i.DesiredItemID,
			&i.Class,
			&i.Priority,
			&i.LastSearchedAt,
			&i.ReleaseDate,
			&i.EligibleAfter,
			&i.SearchCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const recomputePresentCount = `-- name: RecomputePresentCount :exec
UPDATE desired_item
SET present_count = (
      SELECT COUNT(DISTINCT media_ref)
      FROM desired_item_file
      WHERE desired_item_id = desired_item.id AND role = 'primary')
WHERE id = ?
`

// The reconciliation job compares this against present_count. Drift is
// inevitable, so the repair path is not optional.
func (q *Queries) RecomputePresentCount(ctx context.Context, id int64) error {
	_, err := q.db.ExecContext(ctx, recomputePresentCount, id)
	return err
}

